    typealias SwiftType = OfflineProtocol

    public static func lift(_ handle: UInt64) throws -> OfflineProtocol {
        return OfflineProtocol(unsafeFromHandle: handle)
    }

    public static func lower(_ value: OfflineProtocol) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> OfflineProtocol {
