// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.

public enum MessagePriority: Equatable, Hashable {
    
    case low
    case medium
    case high
    case critical



}

#if compiler(>=6)
extension MessagePriority: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMessagePriority: FfiConverterRustBuffer {
    typealias SwiftType = MessagePriority

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MessagePriority {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .low
        
        case 2: return .medium
        
        case 3: return .high
        
        case 4: return .critical
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MessagePriority, into buf: inout [UInt8]) {
        switch value {
        
        
        case .low:
            writeInt(&buf, Int32(1))
        
        
        case .medium:
            writeInt(&buf, Int32(2))
        
        
        case .high:
            writeInt(&buf, Int32(3))
        
        
        case .critical:
            writeInt(&buf, Int32(4))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeMessagePriority_lift(_ buf: RustBuffer) throws -> MessagePriority {
    return try FfiConverterTypeMessagePriority.lift(buf)
